/// Abstract syntax tree node for a mathematical expression.
#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Num(f64),
    UnaryOp {
        op: char,
        operand: Box<Expr>,
    },
    BinOp {
        op: char,
        left: Box<Expr>,
        right: Box<Expr>,
    },
}

/// Parses a mathematical expression string into an AST, respecting operator
/// precedence and parentheses, then serializes it to a string.
///
/// Precedence (lowest to highest):
///   1. `+` `-`
///   2. `*` `/` `%`
///   3. unary `-` `+`
///   4. atoms: numbers, parenthesized sub-expressions
///
/// # Examples
///
/// ```
/// use choucisan::serialize_tree::serialize_tree;
///
/// assert_eq!(serialize_tree("1 + 2 * 3").unwrap(), "(+ 1 (* 2 3))");
/// assert_eq!(serialize_tree("(1 + 2) * 3").unwrap(), "(* (+ 1 2) 3)");
/// assert_eq!(serialize_tree("-3 + 4").unwrap(), "(+ (- 3) 4)");
/// ```
pub fn serialize_tree(input: &str) -> Result<String, String> {
    let expr = Parser::new(input).parse()?;
    Ok(expr.to_string())
}

// ---------------------------------------------------------------------------
// AST Display (S-expression style)
// ---------------------------------------------------------------------------

impl std::fmt::Display for Expr {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Expr::Num(n) => {
                if *n == (*n as i64) as f64 {
                    write!(f, "{}", *n as i64)
                } else {
                    write!(f, "{n}")
                }
            }
            Expr::UnaryOp { op, operand } => write!(f, "({op} {operand})"),
            Expr::BinOp { op, left, right } => write!(f, "({op} {left} {right})"),
        }
    }
}

// ---------------------------------------------------------------------------
// Recursive-descent parser
// ---------------------------------------------------------------------------

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Num(f64),
    Op(char),
    LParen,
    RParen,
}

impl Parser {
    fn new(input: &str) -> Self {
        Self {
            tokens: tokenize(input),
            pos: 0,
        }
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn advance(&mut self) -> Option<Token> {
        if self.pos < self.tokens.len() {
            let tok = self.tokens[self.pos].clone();
            self.pos += 1;
            Some(tok)
        } else {
            None
        }
    }

    fn parse(mut self) -> Result<Expr, String> {
        let expr = self.parse_add_sub()?;
        if self.pos < self.tokens.len() {
            return Err(format!("unexpected token: {:?}", self.tokens[self.pos]));
        }
        Ok(expr)
    }

    /// Level 1: addition and subtraction (lowest precedence).
    fn parse_add_sub(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_mul_div()?;
        while self.peek() == Some(&Token::Op('+')) || self.peek() == Some(&Token::Op('-')) {
            let op = match self.advance().unwrap() {
                Token::Op(c) => c,
                _ => unreachable!(),
            };
            let right = self.parse_mul_div()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    /// Level 2: multiplication, division, and modulo.
    fn parse_mul_div(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_unary()?;
        while matches!(self.peek(), Some(&Token::Op('*' | '/' | '%'))) {
            let op = match self.advance().unwrap() {
                Token::Op(c) => c,
                _ => unreachable!(),
            };
            let right = self.parse_unary()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    /// Level 3: unary prefix operators (`-`, `+`).
    fn parse_unary(&mut self) -> Result<Expr, String> {
        if matches!(self.peek(), Some(&Token::Op('-' | '+'))) {
            let op = match self.advance().unwrap() {
                Token::Op(c) => c,
                _ => unreachable!(),
            };
            let operand = self.parse_unary()?;
            return Ok(Expr::UnaryOp {
                op,
                operand: Box::new(operand),
            });
        }
        self.parse_atom()
    }

    /// Level 4: numbers and parenthesized sub-expressions.
    fn parse_atom(&mut self) -> Result<Expr, String> {
        match self.advance() {
            Some(Token::Num(n)) => Ok(Expr::Num(n)),
            Some(Token::LParen) => {
                let expr = self.parse_add_sub()?;
                match self.advance() {
                    Some(Token::RParen) => Ok(expr),
                    _ => Err("expected ')'".to_string()),
                }
            }
            Some(tok) => Err(format!("unexpected token: {tok:?}")),
            None => Err("unexpected end of input".to_string()),
        }
    }
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

fn tokenize(input: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut chars = input.chars().peekable();

    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
            continue;
        }

        if c.is_ascii_digit() || c == '.' {
            let mut num_str = String::new();
            while let Some(&d) = chars.peek() {
                if d.is_ascii_digit() || d == '.' {
                    num_str.push(d);
                    chars.next();
                } else {
                    break;
                }
            }
            tokens.push(Token::Num(num_str.parse().unwrap()));
        } else if matches!(c, '+' | '-' | '*' | '/' | '%') {
            tokens.push(Token::Op(c));
            chars.next();
        } else if c == '(' {
            tokens.push(Token::LParen);
            chars.next();
        } else if c == ')' {
            tokens.push(Token::RParen);
            chars.next();
        } else {
            // Skip unknown characters silently to keep the parser resilient.
            chars.next();
        }
    }

    tokens
}

