    }

    #[test]
    fn test_unary_in_expression() {
        assert_eq!(serialize_tree("-3 + 4").unwrap(), "(+ (- 3) 4)");
    }

    #[test]
    fn test_double_negation() {
        assert_eq!(serialize_tree("--5").unwrap(), "(- (- 5))");
    }

    #[test]
    fn test_unary_after_operator() {
        // 5 * -2  =>  (* 5 (- 2))
        assert_eq!(serialize_tree("5 * -2").unwrap(), "(* 5 (- 2))");
    }

